import ast, pathlib, sys
bad = []
for path in sorted(pathlib.Path("shop/domain").rglob("*.py")) + sorted(pathlib.Path("shop/app").rglob("*.py")):
    source = path.read_text()
    if "paypal" in source.lower():
        bad.append(f"{path}: mentions PayPal")
    for node in ast.walk(ast.parse(source)):
        names = [alias.name for alias in node.names] if isinstance(node, ast.Import) else [node.module or ""] if isinstance(node, ast.ImportFrom) else []
        for name in names:
            if name.split(".")[0] in {"adapters", "main", "urllib", "http", "requests", "httpx", "json"}:
                bad.append(f"{path}:{node.lineno} imports {name}")
print(bad or "domain and app import no adapter, HTTP, or PayPal code")
sys.exit(1 if bad else 0)
